fn ring(cx: i32, cy: i32, r: i32, col: i32) {
    let mut a: i32 = 0;
    while a < 256 {
        let x0: i32 = cx + (r * host::math::cos(a)) / 256;
        let y0: i32 = cy + (r * host::math::sin(a)) / 256;
        let x1: i32 = cx + (r * host::math::cos(a + 8)) / 256;
        let y1: i32 = cy + (r * host::math::sin(a + 8)) / 256;
        host::display::draw_line(x0, y0, x1, y1, col);
        a = a + 8;
    }
}

fn frame(t: i32) {
    host::display::clear(0x001000);
    let cx: i32 = host::display::width() / 2;
    let cy: i32 = host::display::height() / 2;
    ring(cx, cy, 50, 0x114411);
    ring(cx, cy, 100, 0x114411);
    ring(cx, cy, 150, 0x114411);
    let mut k: i32 = 5;
    while k >= 0 {
        let a: i32 = t * 2 - k * 3;
        let x: i32 = cx + (150 * host::math::cos(a)) / 256;
        let y: i32 = cy + (150 * host::math::sin(a)) / 256;
        let g: i32 = 220 - k * 35;
        host::display::draw_line(cx, cy, x, y, g << 8);
        k = k - 1;
    }
    let ba: i32 = 40;
    let bx: i32 = cx + (95 * host::math::cos(ba)) / 256;
    let by: i32 = cy + (95 * host::math::sin(ba)) / 256;
    let diff: i32 = (t * 2 - ba) & 255;
    let mut glow: i32 = 255 - diff;
    if glow < 60 { glow = 60; }
    host::display::fill_rect(bx - 3, by - 3, 6, 6, (glow << 8) | (glow / 3));
    host::display::present();
}
